<?php
namespace Tests\Feature;
use App\Models\Institution;use App\Models\User;use Database\Seeders\RolesAndPermissionsSeeder;use Illuminate\Foundation\Testing\RefreshDatabase;use Tests\TestCase;
class LocationDomainTest extends TestCase {use RefreshDatabase;protected function setUp():void{parent::setUp();$this->seed(RolesAndPermissionsSeeder::class);}public function test_authenticated_viewer_can_view_location_tree():void{$u=User::factory()->create();$u->assignRole('Viewer');Institution::create(['name'=>'Test University','slug'=>'test-university']);$this->actingAs($u)->get('/locations')->assertOk()->assertSee('Test University');}public function test_network_admin_can_create_campus():void{$u=User::factory()->create();$u->assignRole('Network Admin');$i=Institution::create(['name'=>'Test','slug'=>'test']);$this->actingAs($u)->postJson("/api/institutions/{$i->id}/campuses",['name'=>'Main Campus','code'=>'MAIN'])->assertCreated()->assertJson(['code'=>'MAIN']);$this->assertDatabaseHas('campuses',['institution_id'=>$i->id,'code'=>'MAIN']);}public function test_viewer_cannot_manage_locations():void{$u=User::factory()->create();$u->assignRole('Viewer');$i=Institution::create(['name'=>'Test','slug'=>'test']);$this->actingAs($u)->postJson("/api/institutions/{$i->id}/campuses",['name'=>'Main','code'=>'M'])->assertForbidden();}}
